    <div className="planningScheduleToolbar"><label>Buscar no cronograma<input aria-label="Buscar no cronograma" type="search" placeholder="Ação, responsável, local ou contato" value={search} onChange={e=>setSearch(e.target.value)}/></label><button type="button" className="planningFilterToggle" aria-expanded={filtersOpen} aria-controls="planning-schedule-filters" onClick={()=>setFiltersOpen(value=>!value)}>Filtros{filterCount?' · '+filterCount:''}</button></div>
    {filtersOpen&&<div id="planning-schedule-filters" className="planningScheduleFilters"><label>Responsável<select aria-label="Responsável do cronograma" value={owner} onChange={e=>setOwner(e.target.value)}><option value="all">Todos</option><option value="unassigned">Sem responsável</option>{owner!=='all'&&owner!=='unassigned'&&!owners.includes(owner)&&<option value={owner}>{owner} · Não disponível nesta data</option>}{owners.map(value=><option key={value} value={value}>{value}</option>)}</select></label><label>Situação<select aria-label="Situação do cronograma" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Todas</option><option value="open">A realizar</option><option value="done">Realizadas</option><option value="blocked">Bloqueadas por dependência</option></select></label><label>A partir de<input aria-label="Horário inicial do cronograma" type="time" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Até<input aria-label="Horário final do cronograma" type="time" value={until} onChange={e=>setUntil(e.target.value)}/></label><small>A faixa considera o horário de início de cada ação.</small></div>}
