function AttachmentManager({item,installmentId,paymentId,onChange,onClose,sync,onBusy,documentApi}) {
  const[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
  const changeBusy=value=>{setBusy(value);onBusy(value)};
  const entry=paymentId?paymentHistory((item.installments||[]).find(p=>p.id===installmentId)||{}).find(h=>h.id===paymentId):null;
  const attachments=paymentId?entry?.attachments||[]:item.attachments||[];
  const target={expenseId:item.id,installmentId:installmentId||'',paymentId:paymentId||''};
  const upload=async file=>{if(!file)return;if(file.size>5*1024*1024||!['application/pdf','image/jpeg','image/png','image/webp'].includes(file.type)){setError('Use PDF, JPG, PNG ou WebP de até 5 MB.');return}changeBusy(true);setError('');setMessage('');try{const form=new FormData();Object.entries(target).forEach(([k,v])=>form.set(k,v));form.set('file',file);const result=await documentApi('upload',form);onChange(result.expense,result.revision);setMessage('Documento anexado.')}catch(err){setError(err.message)}finally{changeBusy(false)}};
  const open=async document=>{changeBusy(true);setError('');const win=window.open('about:blank','_blank');if(win)win.opener=null;try{const result=await planningApi('file_url',{path:document.path});if(win)win.location.replace(result.url);else setError('Permita abrir uma nova aba para visualizar o documento.')}catch(err){win?.close();setError(err.message)}finally{changeBusy(false)}};
  const remove=async document=>{if(!confirm('Remover este documento? O arquivo será excluído permanentemente.'))return;changeBusy(true);setError('');setMessage('');try{const result=await documentApi('remove_file',{...target,path:document.path});onChange(result.expense,result.revision);setMessage('Documento removido.')}catch(err){setError(err.message)}finally{changeBusy(false)}};
  return <div><h3>{paymentId?'Comprovantes do pagamento':'Documentos do serviço'}</h3><p className="planningPaymentIntro">{item.description}{entry?' · '+money(entry.amount)+(entry.reversedAt?' · Estornado':''):''}</p><p className="planningFormHint">PDF, JPG, PNG ou WebP de até 5 MB. Os documentos têm acesso privado.</p>{sync!=='synced'&&<p className="planningFormHint">Aguarde a sincronização para anexar documentos.</p>}
    <label className="planningFileInput">{busy?'Processando…':'Anexar documento'}<input aria-label="Anexar documento" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" disabled={busy||sync!=='synced'||attachments.length>=20} onChange={e=>{upload(e.target.files?.[0]);e.target.value=''}}/></label>
    {error&&<p className="error" role="alert">{error}</p>}{message&&<p className="planningFormHint" role="status">{message}</p>}
    {attachments.length?<ul className="planningDocumentList">{attachments.map(document=><li key={document.path}><div><b>{document.name}</b><span>{(document.size/1024).toFixed(0)} KB · {fmt(eventToday(new Date(document.uploadedAt)))}</span></div><button type="button" disabled={busy} aria-label={`Abrir ${document.name}`} onClick={()=>open(document)}>Abrir</button><button type="button" disabled={busy||sync!=='synced'} className="danger" aria-label={`Remover documento ${document.name}`} onClick={()=>remove(document)}>Remover</button></li>)}</ul>:<p className="planningEmpty">Nenhum documento anexado.</p>}<div className="modalActions"><button type="button" disabled={busy} onClick={onClose}>Fechar</button></div>
  </div>;
}
function ConflictDetails({value,field}) {
  if(value===undefined)return <p>Registro removido</p>;
  if(typeof value==='number')return <p>{field.startsWith('budgets:')?money(value):value}</p>;if(typeof value==='boolean'||typeof value==='string')return <p>{typeof value==='boolean'?(value?'Sim':'Não'):value}</p>;
  const item=value.item||value;
  const fields=[['Categoria',item.category],['Responsável',item.responsible],['Fornecedor',item.supplier],['Situação',item.status==='done'?'Realizada':item.status?'A realizar':''],['Prioridade',({high:'Alta',medium:'Média',low:'Baixa'})[item.priority]],['Prazo',fmt(item.due)],['Cronograma',[fmt(item.eventDate),item.eventTime,item.eventEnd].filter(Boolean).join(' · ')],['Contato',item.contact],['Local',item.place],['Serviço vinculado',item.expenseId?'Sim':'Não'],['Observação',item.notes]];
  return <div className="planningConflictDetails">{fields.filter(([,v])=>v).map(([label,v])=><p key={label}><b>{label}:</b> {v}</p>)}{item.subtasks?.map(step=><p key={step.id}>{step.done?'Concluída':'Pendente'}: {step.title}</p>)}{item.installments?.map(p=><div key={p.id}><p><b>{p.label||'Parcela'}:</b> {money(p.amount)} · Pago: {money(p.paidAmount)} · Vencimento: {fmt(p.due)||'Sem data'}</p>{paymentHistory(p).map(h=><p key={h.id}>{h.reversedAt?'Estornado':'Pagamento'}: {money(h.amount)} · {fmt(h.paidAt)} · {h.payment}{h.reversalReason?' · '+h.reversalReason:''}</p>)}</div>)}{[...(item.attachments||[]),...(item.installments||[]).flatMap(p=>(p.payments||[]).flatMap(h=>h.attachments||[]))].map(d=><p key={d.id}>Documento: {d.name}</p>)}{item.proposals?.map(p=><p key={p.id}>{p.supplier} · {money(p.amount)} · {p.terms}{p.validUntil?' · Validade: '+fmt(p.validUntil):''}</p>)}{value.deletedAt&&<p>Enviado à lixeira em {new Date(value.deletedAt).toLocaleString('pt-BR')}</p>}</div>;
}
function ConflictReview({conflict,onResolve}) {
  const[choices,setChoices]=useState({});
  const describe=value=>value===undefined?'Registro removido':typeof value==='number'?money(value):typeof value==='boolean'?(value?'Sim':'Não'):typeof value==='string'?({confirmed:'Convidados confirmados',estimate:'Estimativa de público'}[value]||value):[value.title||value.description||value.item?.title||value.item?.description,value.responsible,value.due?`Prazo: ${fmt(value.due)}`:'',value.eventTime?`Horário: ${value.eventTime}`:'',value.status==='done'?'Realizada':'',value.subtasks?.length?`Etapas: ${taskProgress(value).done}/${taskProgress(value).total}`:'',value.installments?`Contratado: ${money(expenseTotals(value).planned)} · Pago: ${money(expenseTotals(value).paid)}`:'',value.notes].filter(Boolean).join(' · ');
  return <section className="planningConflict" role="alert"><h3>Este planejamento foi alterado em outro dispositivo</h3><p>As alterações em registros diferentes serão combinadas. Para os registros abaixo, escolha a versão que deseja manter antes de continuar.</p>{conflict.conflicts.map(c=><fieldset key={c.key}><legend>{c.label}</legend>{[['local','Minha edição',c.local],['remote','Outro dispositivo',c.remote]].map(([value,label,item])=><label key={value}><input type="radio" name={c.key} checked={choices[c.key]===value} onChange={()=>setChoices(x=>({...x,[c.key]:value}))}/><span><b>{label}</b><small>{c.key==='guestSettings:estimatedGuests'&&typeof item==='number'?item+' pessoas':describe(item)}</small><details><summary>Ver dados completos</summary><ConflictDetails value={item} field={c.key}/></details></span></label>)}</fieldset>)}<button type="button" className="primary" disabled={conflict.conflicts.some(c=>!choices[c.key])} onClick={()=>onResolve(choices)}>Aplicar escolhas e sincronizar</button></section>;
}
function Planning(){
  const[data,setData]=useState(readLocal),[modal,setModal]=useState(null);
  const {sync,conflict,resolve,retry,documentApi,acceptExpense}=usePlanningSync({data,setData,api:planningApi,normalize,storageKey:KEY});
  const[taskSearch,setTaskSearch]=useState(''),[taskCat,setTaskCat]=useState('all'),[taskView,setTaskView]=useState('open'),[taskOwner,setTaskOwner]=useState('all'),[taskPeriod,setTaskPeriod]=useState('all'),[taskStatus,setTaskStatus]=useState('all');
  const[expenseSearch,setExpenseSearch]=useState(''),[expenseCat,setExpenseCat]=useState('all'),[expenseView,setExpenseView]=useState('open'),[expensePeriod,setExpensePeriod]=useState('all'),[expenseStatus,setExpenseStatus]=useState('all');
  const[currentDay,setCurrentDay]=useState(today);
  const[taskSection,setTaskSection]=useState('checklist'),[financeSection,setFinanceSection]=useState('services');
  const[taskFiltersOpen,setTaskFiltersOpen]=useState(false),[expenseFiltersOpen,setExpenseFiltersOpen]=useState(false),[taskSort,setTaskSort]=useState('due'),[expenseSort,setExpenseSort]=useState('due');
  const taskPanel=useRef(null),expensePanel=useRef(null);
  useEffect(()=>{const refresh=()=>setCurrentDay(today()),clock=setInterval(refresh,60000);window.addEventListener('focus',refresh);return()=>{clearInterval(clock);window.removeEventListener('focus',refresh)}},[]);
  useEffect(()=>{if(conflict)setModal(null)},[conflict]);
  const summary=useMemo(()=>planningSnapshot(data,currentDay),[data,currentDay]);
  const owners=[...new Set(data.tasks.map(t=>t.responsible?.trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  const taskCounts={open:data.tasks.filter(t=>t.status!=='done').length,done:data.tasks.filter(t=>t.status==='done').length};
  const tasks=data.tasks.filter(t=>
    (taskView==='done'?t.status==='done':t.status!=='done')&&
    (taskCat==='all'||t.category===taskCat)&&
    (taskOwner==='all'||(taskOwner==='unassigned'?!t.responsible?.trim():t.responsible?.trim()===taskOwner))&&
    searchText(`${t.title} ${t.responsible||''} ${t.notes||''}`).includes(searchText(taskSearch))&&
    matchesPeriod(t.due,taskPeriod,currentDay)&&
    (taskStatus==='all'||(taskStatus==='overdue'&&matchesPeriod(t.due,'overdue',currentDay))||(taskStatus==='undated'&&!t.due)||(taskStatus==='blocked'&&taskDependencies(t,data.tasks).length>0))
  ).sort((a,b)=>taskSort==='completed'?(b.completedAt||'').localeCompare(a.completedAt||''):(taskSort==='title'?a.title.localeCompare(b.title,'pt-BR'):taskSort==='priority'?({high:0,medium:1,low:2}[a.priority]??3)-({high:0,medium:1,low:2}[b.priority]??3)||(a.due||'9999').localeCompare(b.due||'9999'):(a.due||'9999').localeCompare(b.due||'9999')));
  // A service is settled only when every installment has no remaining balance.
  const allExpenses=data.expenses.map(e=>({...e,totals:expenseTotals(e,currentDay)}));
  const expenseCounts={open:allExpenses.filter(e=>e.totals.state!=='paid').length,paid:allExpenses.filter(e=>e.totals.state==='paid').length};
  const settledValue=allExpenses.filter(e=>e.totals.state==='paid').reduce((sum,e)=>sum+e.totals.paid,0);
  const expenses=allExpenses.filter(e=>{
    const settled=e.totals.state==='paid';
    if(expenseView==='paid'?!settled:settled)return false;
    if(expenseCat!=='all'&&e.category!==expenseCat)return false;
    if(!searchText(`${e.description} ${e.supplier||''} ${e.notes||''} ${(e.installments||[]).map(p=>p.label).join(' ')}`).includes(searchText(expenseSearch)))return false;
    if(expenseStatus==='overdue'&&!e.totals.overdue)return false;
    if(expenseStatus==='partial'&&!(e.totals.paid>0&&e.totals.balance>0))return false;
    if(expenseStatus==='unpaid'&&e.totals.paid>0)return false;
    if(expensePeriod==='all')return true;
    const payments=(e.installments||[]).filter(p=>settled?Number(p.paidAmount)>0:installmentBalance(p)>0);
    return payments.some(p=>matchesPeriod(settled?p.paidAt:p.due,expensePeriod,currentDay))||(expensePeriod==='undated'&&(e.totals.unallocated>0||!payments.length));
  }).sort((a,b)=>{
    const date=e=>(e.installments||[]).filter(p=>expenseView==='paid'?Number(p.paidAmount)>0:installmentBalance(p)>0).map(p=>(expenseView==='paid'?p.paidAt:p.due)||'9999').sort()[0]||'9999';
    return expenseSort==='balance'?b.totals.balance-a.totals.balance:expenseSort==='name'?a.description.localeCompare(b.description,'pt-BR'):expenseSort==='value'?b.totals.planned-a.totals.planned:date(a).localeCompare(date(b));
  });
  const clearTasks=()=>{setTaskSearch('');setTaskCat('all');setTaskOwner('all');setTaskPeriod('all');setTaskStatus('all')};
  const clearExpenses=()=>{setExpenseSearch('');setExpenseCat('all');setExpensePeriod('all');setExpenseStatus('all')};
  const focusPanel=ref=>requestAnimationFrame(()=>{ref.current?.scrollIntoView({behavior:'smooth',block:'start'});ref.current?.focus({preventScroll:true})});
  const filterAlert=(type,period)=>{
    if(type==='task'){setTaskSection('checklist');clearTasks();setTaskView('open');setTaskPeriod(period);setTaskFiltersOpen(true);focusPanel(taskPanel)}
    else{setFinanceSection('services');clearExpenses();setExpenseView('open');setExpensePeriod(period);setExpenseFiltersOpen(true);focusPanel(expensePanel)}
  };
  const taskFilterCount=[taskCat!=='all',taskOwner!=='all',taskPeriod!=='all',taskStatus!=='all'].filter(Boolean).length;
  const expenseFilterCount=[expenseCat!=='all',expensePeriod!=='all',expenseStatus!=='all'].filter(Boolean).length;
  const taskFiltersActive=taskSearch||taskCat!=='all'||taskOwner!=='all'||taskPeriod!=='all'||taskStatus!=='all';
  const expenseFiltersActive=expenseSearch||expenseCat!=='all'||expensePeriod!=='all'||expenseStatus!=='all';
  const toggle=t=>setData(d=>togglePlanningTask(d,t.id,today()));
  const toggleStep=(taskId,stepId)=>setData(d=>togglePlanningSubtask(d,taskId,stepId));
  const saveTask=f=>{setData(d=>({...d,tasks:f.id?d.tasks.map(x=>x.id===f.id?f:x):[{...f,id:id(),status:'todo',completedAt:''},...d.tasks]}));setModal(null)};
  const updateDocumentExpense=(expense,revision)=>{acceptExpense(expense,revision);setModal(m=>m?.type==='documents'&&m.item.id===expense.id?{...m,item:expense}:m)};
  const moveToTrash=(type,itemId)=>{try{setData(trashPlanningItem(data,type,itemId,id));setModal(null)}catch(err){alert(err.message)}};
  const saveExpense=f=>{const {totals,linkedActionIds,...expense}=f;const saved={...expense,id:expense.id||id()};try{setData(d=>modal?.quoteId?contractPlanningQuote(d,modal.quoteId,modal.proposalId,saved,linkedActionIds):saveExpenseWithActions(d,saved,linkedActionIds));setModal(null);if(modal?.quoteId)setFinanceSection('services')}catch(error){alert(error.message)}};
  const alerts=[
    {type:'task',period:'overdue',tone:'overdue',count:summary.overdueTasks,value:`${summary.overdueTasks} ação${summary.overdueTasks===1?'':'s'}`,label:summary.overdueTasks===1?'atrasada':'atrasadas'},
    {type:'task',period:'next7',tone:'soon',count:summary.soonTasks,value:`${summary.soonTasks} ação${summary.soonTasks===1?'':'s'}`,label:summary.soonTasks===1?'vence em até 7 dias':'vencem em até 7 dias'},
    {type:'expense',period:'overdue',tone:'overdue',count:summary.overduePayments,value:money(summary.overdueValue),label:`vencidos · ${summary.overduePayments} pagamento(s)`},
    {type:'expense',period:'next7',tone:'soon',count:summary.soonPayments,value:money(summary.soonValue),label:`em até 7 dias · ${summary.soonPayments} pagamento(s)`}
  ];
  return <>
    <div className="planningIntro"><span className="eyebrow">PLANEJAMENTO DO EVENTO</span><h2>Organização do Chá do Oliver</h2><p>Ações, pagamentos e prazos para acompanhar até o dia do chá.</p><small className={'planningSync '+sync}>{sync==='loading'?'Carregando planejamento…':sync==='saving'?'Salvando…':sync==='synced'?'✓ Sincronizado entre dispositivos':sync==='conflict'?'⚠ Edições simultâneas — escolha qual versão manter':'⚠ Offline — alterações salvas neste dispositivo'}</small>{sync==='offline'&&<button type="button" onClick={retry}>Tentar sincronizar</button>}</div>
    {conflict&&<ConflictReview conflict={conflict} onResolve={resolve}/>}
    <details className="planningAttention"><summary>Precisa da sua atenção <span>{summary.overdueTasks+summary.soonTasks} ações · {money(summary.overdueValue+summary.soonValue)} em pagamentos <small>Ver pendências</small></span></summary><p>Selecione um alerta para consultar as pendências. Os valores mostram o saldo das parcelas.</p><div className="planningAlertGrid">{alerts.map(a=><button key={a.type+a.period} type="button" disabled={!a.count} className={'planningAlertButton '+(a.count?a.tone:'clear')} onClick={()=>filterAlert(a.type,a.period)}><strong>{a.value}</strong><span>{a.label}</span>{a.count>0&&<small>Ver pendências →</small>}</button>)}</div>{!alerts.some(a=>a.count>0)&&<p className="planningAllClear">Tudo em dia: nenhuma pendência vencida ou nos próximos 7 dias.</p>}</details>
    <div className="planningSummary"><div><span>AÇÕES REALIZADAS</span><strong>{taskCounts.done}/{data.tasks.length}</strong><small>{taskCounts.open} a realizar</small></div><div><span>CONTRATADO</span><strong>{money(summary.planned)}</strong><small>total dos gastos</small></div><div><span>PAGO</span><strong>{money(summary.paid)}</strong><small>pagamentos realizados</small></div><div><span>A QUITAR</span><strong>{money(summary.open)}</strong><small>saldo dos serviços</small></div></div>
    <div className="planningColumns" inert={conflict||sync==='loading'?true:undefined}>
      <section className="planningPanel" ref={taskPanel} tabIndex={-1} aria-label="Ações do planejamento">
        <div className="planningPanelHead"><div><span className="eyebrow">AÇÕES</span><h3>Organização</h3></div><button type="button" onClick={()=>setModal(taskSection==='schedule'?{type:'task',initialSchedule:true,initialDate:'2026-12-04'}:{type:'task'})}>{taskSection==='schedule'?'+ Novo horário':'+ Nova tarefa'}</button></div>
        <PlanningTabs id="planning-actions" label="Funções de Ações" value={taskSection} onChange={setTaskSection} options={[["checklist","Checklist"],["schedule","Cronograma"]]}/>
        <div role="tabpanel" id="planning-actions-panel" aria-labelledby={'planning-actions-'+taskSection}>
        {taskSection==='schedule'?<EventSchedule tasks={data.tasks} onAdd={date=>setModal({type:'task',initialSchedule:true,initialDate:date})} onEdit={item=>setModal({type:'task',item})} onToggle={toggle}/>:<>

        <div className="filterPills planningViewSwitch" aria-label="Situação das ações">{[['open','A realizar'],['done','Realizadas']].map(([view,label])=><button key={view} type="button" aria-pressed={taskView===view} className={taskView===view?'active':''} onClick={()=>{setTaskView(view);setTaskSort(view==='done'?'completed':'due');setTaskStatus('all');setTaskPeriod('all')}}>{label} · {taskCounts[view]}</button>)}</div>
        <FilterToolbar search={taskSearch} onSearch={setTaskSearch} placeholder="Tarefa, responsável ou observação" open={taskFiltersOpen} onToggle={()=>setTaskFiltersOpen(x=>!x)} count={taskFilterCount} sort={taskSort} onSort={setTaskSort} sortLabel="Ordenar ações" filterId="planning-task-filters" options={[["due","Prazo"],["priority","Prioridade"],["title","Nome"],...(taskView==='done'?[["completed","Conclusão (recentes)"]]:[])]}/>
        {taskFiltersOpen&&<div id="planning-task-filters" className="planningFilters planningFiltersV2">
          <label>Categoria<select aria-label="Categoria" value={taskCat} onChange={e=>setTaskCat(e.target.value)}><option value="all">Todas as categorias</option>{CATS.map(x=><option key={x}>{x}</option>)}</select></label>
          <label>Responsável<select aria-label="Responsável" value={taskOwner} onChange={e=>setTaskOwner(e.target.value)}><option value="all">Todos os responsáveis</option><option value="unassigned">Sem responsável</option>{owners.map(x=><option key={x}>{x}</option>)}</select></label>
          <PeriodFilter value={taskPeriod} onChange={setTaskPeriod} label="Período do prazo"/>
          <label>Status<select aria-label="Status" value={taskStatus} onChange={e=>setTaskStatus(e.target.value)}><option value="all">{taskView==='open'?'Todas a realizar':'Todas realizadas'}</option>{taskView==='open'&&<><option value="overdue">Atrasadas</option><option value="blocked">Bloqueadas por dependência</option></>}<option value="undated">Sem prazo</option></select></label>
        </div>}
        <div className="planningFilterMeta"><span aria-live="polite">{tasks.length} de {taskCounts[taskView]} ações</span>{taskFiltersActive&&<button type="button" className="planningClear" onClick={clearTasks}>Limpar filtros</button>}</div>
        <div className="taskList">{tasks.map(t=><article className={'taskItem '+(t.status==='done'?'done':'')} key={t.id}><button type="button" className="taskCheck" aria-label={`${t.status==='done'?'Reabrir':'Concluir'} ${t.title}`} aria-pressed={t.status==='done'} disabled={t.status!=='done'&&(taskProgress(t).pending||taskDependencies(t,data.tasks).length>0)} title={t.status!=='done'&&taskDependencies(t,data.tasks).length?'Conclua as dependências primeiro':t.status!=='done'&&taskProgress(t).pending?'Conclua as etapas primeiro':undefined} onClick={()=>toggle(t)}>{t.status==='done'?'✓':''}</button><div><b>{t.title}</b><span>{t.category} · {t.responsible||'Sem responsável'}{t.due?' · '+fmt(t.due):''}</span>{t.expenseId&&(()=>{const linked=data.expenses.find(e=>e.id===t.expenseId);if(!linked)return <span>Serviço vinculado indisponível</span>;const financial=expenseTotals(linked,currentDay);return <button type="button" className="planningTaskExpense" aria-label={`Abrir serviço ${linked.description} de ${t.title}`} onClick={()=>setModal({type:'expense',item:linked})}>{linked.description} · {financial.state==='paid'?'Quitado':'Saldo '+money(financial.balance)}</button>})()}{t.status==='done'?<span>Realizada{t.completedAt?' em '+fmt(t.completedAt):''}</span>:<DueBadge date={t.due} currentDay={currentDay}/>}<TaskDependencies task={t} tasks={data.tasks} onEdit={item=>setModal({type:'task',item})}/><TaskSteps task={t} onToggle={toggleStep}/></div><em className={'priority '+t.priority}>{t.priority==='high'?'Alta':t.priority==='medium'?'Média':'Baixa'}</em><div className="planningRecordActions"><button type="button" className="iconAction" aria-label={`Editar tarefa ${t.title}`} onClick={()=>setModal({type:'task',item:t})}>Editar</button><button type="button" className="iconAction" disabled={data.tasks.length>=500} aria-label={`Duplicar tarefa ${t.title}`} onClick={()=>setModal({type:'task',item:duplicatePlanningTask(t,id)})}>Duplicar</button></div></article>)}{!tasks.length&&<div className="planningEmpty">Nenhuma ação neste filtro.{taskFiltersActive?' Limpe os filtros para ampliar a consulta.':''}</div>}</div>
        </>}
        </div>
      </section>
      <section className="planningPanel" ref={expensePanel} tabIndex={-1} aria-label="Financeiro do planejamento">
        <div className="planningPanelHead"><div><span className="eyebrow">FINANCEIRO</span><h3>Gestão financeira</h3></div>{financeSection==='services'&&<button type="button" onClick={()=>setModal({type:'expense'})}>+ Novo gasto</button>}{financeSection==='quotes'&&<button type="button" disabled={data.quotes.length>=500} onClick={()=>setModal({type:'quote'})}>+ Nova cotação</button>}</div>
        <PlanningTabs id="planning-finance" label="Funções do Financeiro" value={financeSection} onChange={setFinanceSection} options={[["services","Serviços"],["payments","Pagamentos"],["quotes","Cotações"],["analysis","Análise"]]}/>
        <div role="tabpanel" id="planning-finance-panel" aria-labelledby={'planning-finance-'+financeSection}>
        {financeSection==='payments'?<UpcomingPayments expenses={data.expenses} currentDay={currentDay} onEdit={item=>setModal({type:'expense',item})} onPay={(item,installmentId)=>setModal({type:'payment',item,installmentId})}/>:financeSection==='analysis'?<><CostPerGuest expenses={data.expenses} settings={data.guestSettings} onChange={guestSettings=>setData(d=>({...d,guestSettings}))}/><BudgetOverview expenses={data.expenses} budgets={data.budgets} onEdit={()=>setModal({type:'budget'})}/></>:financeSection==='quotes'?<QuoteBoard quotes={data.quotes} expenses={data.expenses} trash={data.trash} currentDay={currentDay} onEdit={item=>setModal({type:'quote',item})} onOpenExpense={item=>{setFinanceSection('services');setModal({type:'expense',item})}} onContract={(quote,proposal)=>setModal({type:'expense',quoteId:quote.id,proposalId:proposal.id,item:{description:quote.title,category:quote.category,supplier:proposal.supplier,contracted:proposal.amount,notes:[proposal.terms,proposal.contact?'Contato: '+proposal.contact:'',proposal.validUntil?'Proposta válida até '+fmt(proposal.validUntil):'',proposal.notes].filter(Boolean).join('\n'),installments:[]}})}/>:<>

        <div className="filterPills planningViewSwitch" aria-label="Situação dos serviços">{[['open','A quitar',summary.open],['paid','Quitados',settledValue]].map(([view,label,value])=><button key={view} type="button" aria-pressed={expenseView===view} className={expenseView===view?'active':''} onClick={()=>{setExpenseView(view);setExpenseStatus('all');setExpensePeriod('all')}}>{label} · {expenseCounts[view]} · {money(value)}</button>)}</div>
        <FilterToolbar search={expenseSearch} onSearch={setExpenseSearch} placeholder="Gasto, fornecedor ou parcela" open={expenseFiltersOpen} onToggle={()=>setExpenseFiltersOpen(x=>!x)} count={expenseFilterCount} sort={expenseSort} onSort={setExpenseSort} sortLabel="Ordenar gastos" filterId="planning-expense-filters" options={[["due","Vencimento"],["balance","Maior saldo"],["name","Nome"],["value","Maior valor contratado"]]}/>
        {expenseFiltersOpen&&<div id="planning-expense-filters" className="planningFilters planningFiltersV2">
          <label>Categoria<select aria-label="Categoria" value={expenseCat} onChange={e=>setExpenseCat(e.target.value)}><option value="all">Todas as categorias</option>{CATS.map(x=><option key={x}>{x}</option>)}</select></label>
          <PeriodFilter value={expensePeriod} onChange={setExpensePeriod} paid={expenseView==='paid'} label={expenseView==='paid'?'Data do pagamento':'Período do vencimento'}/>
          {expenseView==='open'&&<label>Status do serviço<select aria-label="Status do serviço" value={expenseStatus} onChange={e=>setExpenseStatus(e.target.value)}><option value="all">Todos os status</option><option value="unpaid">Sem pagamento</option><option value="partial">Parcialmente pago</option><option value="overdue">Com parcela vencida</option></select></label>}
        </div>}
        <div className="planningFilterMeta"><span aria-live="polite">{expenses.length} de {expenseCounts[expenseView]} serviço(s)</span>{expenseFiltersActive&&<button type="button" className="planningClear" onClick={clearExpenses}>Limpar filtros</button>}</div>
        <div className="expenseList">{expenses.map(e=>{
          const next=(e.installments||[]).filter(p=>installmentBalance(p)>0&&p.due).sort((a,b)=>a.due.localeCompare(b.due))[0];
          const percent=e.totals.planned>0?Math.min(100,Math.round(e.totals.paid/e.totals.planned*100)):0;
          return <article className="planningExpenseCard" key={e.id}>
            <div className="planningExpenseHead"><div><b>{e.description}</b><span>{e.category}{e.supplier?' · '+e.supplier:''}</span><span className={'expenseStatus '+(e.totals.state==='paid'?'paid':e.totals.overdue?'overdue':'open')}>{e.totals.state==='paid'?'Quitado':e.totals.planned>0?'A quitar':'Valor a definir'}</span></div><div className="planningRecordActions"><button type="button" className="iconAction" aria-label={`Editar gasto ${e.description}`} onClick={()=>setModal({type:'expense',item:e})}>Editar</button><button type="button" className="iconAction" disabled={data.expenses.length>=500} aria-label={`Duplicar gasto ${e.description}`} onClick={()=>setModal({type:'expense',item:duplicatePlanningExpense(e)})}>Duplicar</button></div></div>
            <div className="planningExpenseNumbers"><div><small>Contratado</small><strong>{money(e.totals.planned)}</strong></div><div><small>Pago</small><strong>{money(e.totals.paid)}</strong></div><div><small>Saldo a quitar</small><strong>{money(e.totals.balance)}</strong></div></div>
            {e.totals.planned>0&&<div className="planningPaidProgress"><progress max="100" value={percent} aria-label={`Percentual pago de ${e.description}`}/><span>{percent}% pago</span></div>}
            {next&&<div className="planningNextPayment"><span>{next.label||'Próxima parcela'} · {fmt(next.due)}</span><DueBadge date={next.due} currentDay={currentDay}/></div>}
            {e.totals.unallocated>0&&<p className="planningUnallocated">{money(e.totals.unallocated)} ainda sem programação <button type="button" onClick={()=>setModal({type:'expense',item:e})}>Programar</button></p>}
            {e.totals.balance>0&&<button type="button" className="planningRegisterPayment" aria-label={`Registrar pagamento de ${e.description}`} onClick={()=>setModal({type:'payment',item:e})}>Registrar pagamento</button>}
            <button type="button" className="planningDocumentsButton" aria-label={`Documentos de ${e.description}`} onClick={()=>setModal({type:'documents',item:e})}>Documentos · {(e.attachments||[]).length}</button>
            <details className="planningPaymentDetails"><summary>Ver pagamentos · {(e.installments||[]).length}</summary><div className="planningPayments">
              {!(e.installments||[]).length&&<p className="planningEmpty">Nenhum pagamento programado. Edite o serviço para cadastrar parcelas.</p>}
              {(e.installments||[]).map((p,i)=>{
                const balance=installmentBalance(p),settled=balance===0&&Number(p.amount)>0;
                return <div className="planningPayment" key={p.id||i}><div><b>{p.label||'Pagamento'}</b><span>{settled?(p.paidAt?'Pago em '+fmt(p.paidAt):'Data de pagamento não informada'):(p.due?'Vencimento '+fmt(p.due):'Sem vencimento')}{settled?' · '+(p.payment||'Não informado'):''}</span>
                  {settled?<span className="expenseStatus paid">Quitado</span>:<><span className={'expenseStatus '+(Number(p.paidAmount)>0?'partial':'open')}>{Number(p.paidAmount)>0?'Pagamento parcial':'A quitar'}</span>{balance>0&&<DueBadge date={p.due} currentDay={currentDay}/>}</>}
                  {paymentHistory(p).length>0&&<ul className="planningPaymentHistory" aria-label={`Histórico de ${p.label||'pagamento'}`}>{paymentHistory(p).map(h=><li key={h.id} className={h.reversedAt?'reversed':''}>
                    <span>{money(h.amount)} · {h.paidAt?fmt(h.paidAt):'Data não informada'} · {h.payment||'Outros'}</span>
                    {h.reversedAt?<small>Estornado · {fmt(eventToday(new Date(h.reversedAt)))} · {h.reversalReason}</small>:<div className="planningHistoryActions"><button type="button" aria-label={`Editar pagamento ${h.id}`} onClick={()=>setModal({type:'revision',item:e,installmentId:p.id,paymentId:h.id,action:'edit'})}>Editar</button><button type="button" aria-label={`Estornar pagamento ${h.id}`} onClick={()=>setModal({type:'revision',item:e,installmentId:p.id,paymentId:h.id,action:'reverse'})}>Estornar</button></div>}
                    <button type="button" className="planningReceiptButton" aria-label={`Comprovantes do pagamento ${h.id}`} onClick={()=>setModal({type:'documents',item:e,installmentId:p.id,paymentId:h.id})}>Comprovantes · {(h.attachments||[]).length}</button>{h.changes?.length>0&&<details className="planningPaymentChanges"><summary>Correções · {h.changes.length}</summary>{h.changes.map((change,j)=><small key={j}>Anterior: {money(change.amount)} · {change.paidAt?fmt(change.paidAt):'Data não informada'} · {change.payment} · {change.reason||'Correção do lançamento'}</small>)}</details>}
                  </li>)}</ul>}

                </div><div className="planningPaymentValue"><strong>{money(settled?p.paidAmount:balance)}</strong><small>{settled?'valor pago':'saldo a quitar'}{!settled&&Number(p.paidAmount)>0?' · '+money(p.paidAmount)+' já pagos':''}</small></div></div>;
              })}
            </div></details>
          </article>;
        })}{!expenses.length&&<div className="planningEmpty">Nenhum serviço neste filtro.{expenseFiltersActive?' Limpe os filtros para ampliar a consulta.':''}</div>}</div>
        </>}
        </div>
      </section>
    </div>
    <footer className="planningFooter"><button type="button" onClick={()=>setModal({type:'history'})}>Histórico do planejamento</button><button type="button" className="planningExport" onClick={()=>setModal({type:'export'})}>Exportar planejamento</button><button type="button" className="planningTrashButton" disabled={!!conflict||sync==='loading'} onClick={()=>setModal({type:'trash'})}>Lixeira · {data.trash.length}</button></footer>
    {modal&&!conflict&&<Modal guard={['task','expense','quote','budget','payment','revision'].includes(modal.type)} side={['task','expense'].includes(modal.type)} busy={!!modal.busy} onClose={()=>{if(!modal.busy)setModal(null)}}>{modal.type==='history'?<PlanningHistory entries={data.history} onClose={()=>setModal(null)}/>:modal.type==='trash'?<TrashForm entries={data.trash} onRestore={entryId=>{const next=restorePlanningItem(data,entryId);setData(next)}} onClose={()=>setModal(null)}/>:modal.type==='documents'?<AttachmentManager item={modal.item} installmentId={modal.installmentId} paymentId={modal.paymentId} onChange={updateDocumentExpense} onBusy={busy=>setModal(m=>m?.type==='documents'?{...m,busy}:m)} sync={sync} documentApi={documentApi} onClose={()=>setModal(null)}/>:modal.type==='export'?<ExportPlanningForm data={data} currentDay={currentDay} onClose={()=>setModal(null)}/>:modal.type==='quote'?<QuoteForm item={modal.item} categories={CATS} onClose={()=>setModal(null)} onDelete={()=>{if(confirm('Mover esta cotação para a lixeira?'))moveToTrash('quote',modal.item.id)}} onSave={quote=>{setData(d=>({...d,quotes:quote.id?d.quotes.map(q=>q.id===quote.id?quote:q):[{...quote,id:id()},...d.quotes]}));setModal(null)}}/>:modal.type==='budget'?<BudgetForm budgets={data.budgets} onSave={budgets=>{setData(d=>({...d,budgets}));setModal(null)}} onClose={()=>setModal(null)}/>:modal.type==='task'?<TaskForm tasks={data.tasks} item={modal.item||(modal.initialSchedule?{eventDate:modal.initialDate}:undefined)} initialSchedule={modal.initialSchedule} expenses={data.expenses} onClose={()=>setModal(null)} onSave={saveTask} onDelete={()=>{if(confirm('Mover esta tarefa para a lixeira?')){moveToTrash('task',modal.item.id)}}}/>:modal.type==='revision'?<PaymentRevisionForm item={modal.item} installmentId={modal.installmentId} paymentId={modal.paymentId} action={modal.action} onSave={saveExpense} onClose={()=>setModal(null)}/>:modal.type==='payment'?<PaymentForm item={modal.item} initialInstallmentId={modal.installmentId} onSave={saveExpense} onClose={()=>setModal(null)}/>:<ExpenseForm item={modal.item} tasks={data.tasks} linkedTasks={modal.item?data.tasks.filter(t=>t.expenseId===modal.item.id):[]} onClose={()=>setModal(null)} onSave={saveExpense} onDelete={()=>{if(confirm('Mover este gasto e seus pagamentos para a lixeira?')){moveToTrash('expense',modal.item.id)}}}/>}</Modal>}
  </>;
}
